javascript:(async()=>{const W=window,D=document;const load=u=>new Promise((ok,no)=>{let s=D.createElement('script');s.src=u;s.onload=ok;s.onerror=no;(D.head||D.documentElement).appendChild(s)});if(!W.eruda)await load('https://cdn.jsdelivr.net/npm/eruda@3.4.3/eruda.min.js');try{eruda.init({useShadowDom:false,tool:['console','elements','network','resources','sources','info','snippets']})}catch(e){}const esc=s=>String(s??'').replace(/[&<>"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[m]));W.__copy=t=>navigator.clipboard?.writeText(String(t)).then(()=>alert('✅ Copied')).catch(()=>prompt('Copy:',t));W.__SCRAPE_LOGS__=W.__SCRAPE_LOGS__||[];if(!W.__SCRAPER_PATCHED__){W.__SCRAPER_PATCHED__=1;const of=W.fetch;W.fetch=async(...a)=>{let url=String(a[0]?.url||a[0]),opt=a[1]||{},res=await of(...a);try{let c=res.clone(),ct=c.headers.get('content-type')||'',txt=await c.text();W.__SCRAPE_LOGS__.push({type:'fetch',url,method:opt.method||'GET',status:res.status,ct,body:txt.slice(0,5000)})}catch(e){}return res};const xo=XMLHttpRequest.prototype.open,xs=XMLHttpRequest.prototype.send;XMLHttpRequest.prototype.open=function(m,u){this.__m=m;this.__u=u;return xo.apply(this,arguments)};XMLHttpRequest.prototype.send=function(b){this.addEventListener('load',()=>{try{W.__SCRAPE_LOGS__.push({type:'xhr',url:this.__u,method:this.__m,status:this.status,ct:this.getResponseHeader('content-type'),body:String(this.responseText||'').slice(0,5000)})}catch(e){}});return xs.apply(this,arguments)}}function path(el){if(!el)return'';if(el.id)return'#'+(CSS.escape?CSS.escape(el.id):el.id);let p=[];while(el&&el.nodeType===1&&el!==D.body){let s=el.tagName.toLowerCase();if(el.className&&typeof el.className==='string')s+='.'+el.className.trim().split(/\s+/).slice(0,3).map(x=>CSS.escape?CSS.escape(x):x).join('.');let n=[...el.parentNode.children].filter(x=>x.tagName===el.tagName).indexOf(el)+1;s+=`:nth-of-type(${n})`;p.unshift(s);el=el.parentElement}return p.join(' > ')}if(!W.__PICKER_ADDED__){W.__PICKER_ADDED__=1;D.addEventListener('click',e=>{if(!W.__PICK_MODE__)return;e.preventDefault();e.stopPropagation();let s=path(e.target);W.__copy(s);W.__PICK_MODE__=0;console.log('[selector]',s)},true)}function addTool(name,render){try{class T extends eruda.Tool{constructor(){super();this.name=name}init($el){super.init($el);this._$el=$el;this.refresh()}show(){super.show();this.refresh()}refresh(){if(this._$el)this._$el.html(render())}}eruda.add(new T())}catch(e){console.error('add tool failed',name,e)}}const btn='padding:9px;margin:4px;background:#222;color:#fff;border:1px solid #555;border-radius:6px';addTool('scraper',()=>`<div style="padding:12px;font:12px monospace;color:#ddd"><h2>🔧 Scraper</h2><button style="${btn}" onclick="window.__PICK_MODE__=1;alert('Tap element target')">🎯 Pick Selector</button><button style="${btn}" onclick="__copy([...document.querySelectorAll('a')].map(a=>a.href).filter(Boolean).join('\\n'))">🔗 Copy Links</button><button style="${btn}" onclick="__copy([...document.images].map(i=>i.src).filter(Boolean).join('\\n'))">🖼 Copy Images</button><button style="${btn}" onclick="__copy(document.documentElement.outerHTML)">📄 Copy HTML</button><hr><b>Title:</b><br>${esc(D.title)}<br><br><b>URL:</b><br>${esc(location.href)}<hr><b>JSON Scripts:</b><br>${[...D.scripts].map((s,i)=>s.textContent.includes('{')?`#${i} - ${s.textContent.length} chars`:null).filter(Boolean).slice(0,80).join('<br>')||'none'}</div>`);addTool('api',()=>`<div style="padding:12px;font:12px monospace;color:#ddd"><h2>🌐 API Sniffer</h2><button style="${btn}" onclick="__copy(JSON.stringify(window.__SCRAPE_LOGS__,null,2))">📋 Copy Logs</button><button style="${btn}" onclick="window.__SCRAPE_LOGS__=[];alert('cleared')">🧹 Clear</button><p>Reload halaman biar request awal ketangkep.</p>${W.__SCRAPE_LOGS__.slice(-80).reverse().map(x=>`<div style="border-bottom:1px solid #444;padding:8px"><b>${esc(x.method)} ${esc(x.status)}</b> ${esc(x.type)}<br><span style="color:#6cf;word-break:break-all">${esc(x.url)}</span><br><small>${esc(x.ct)}</small><pre style="white-space:pre-wrap;max-height:160px;overflow:auto;background:#111;padding:6px">${esc(x.body).slice(0,1200)}</pre></div>`).join('')||'Belum ada request.'}</div>`);addTool('store',()=>`<div style="padding:12px;font:12px monospace;color:#ddd"><h2>💾 Storage</h2><button style="${btn}" onclick="__copy(document.cookie)">🍪 Copy Cookies</button><button style="${btn}" onclick="__copy(JSON.stringify(localStorage,null,2))">Copy LS</button><button style="${btn}" onclick="__copy(JSON.stringify(sessionStorage,null,2))">Copy SS</button><hr><b>Cookies</b><pre>${esc(D.cookie||'none')}</pre><b>LocalStorage</b><pre>${esc(JSON.stringify(localStorage,null,2))}</pre><b>SessionStorage</b><pre>${esc(JSON.stringify(sessionStorage,null,2))}</pre></div>`);addTool('extract',()=>{let urls=[...D.querySelectorAll('script,img,video,audio,source,link,a,iframe')].map(x=>x.src||x.href).filter(Boolean);return`<div style="padding:12px;font:12px monospace;color:#ddd"><h2>📥 Extract</h2><button style="${btn}" onclick="__copy(${JSON.stringify(urls.join('\n'))})">Copy All URLs (${urls.length})</button><hr>${urls.slice(0,300).map(u=>`<div style="word-break:break-all;border-bottom:1px solid #333;padding:5px">${esc(u)}</div>`).join('')||'No URL'}</div>`});eruda.show();})();
